const f = $input.first().json;

// Field names match formLabels exactly.
const url = String(f['GetHookd Brand URL'] || '').trim();
const name = String(f['Brand Name'] || '').trim();
const sinceDateRaw = f['Monitor ads launched on or after'];
const backfillChoice = String(f['Backfill historical ads now?'] || '');
const accountType = String(f['Account Type'] || 'main').toLowerCase();

// Extract brand_id from URL: matches /brands/<digits>
const match = url.match(/\/brands\/(\d+)/);
if (!match) {
  throw new Error('Invalid GetHookd URL — expected pattern like https://app.gethookd.ai/brands/12345. Got: ' + url);
}
const gethookdBrandId = parseInt(match[1], 10);
if (!gethookdBrandId || gethookdBrandId <= 0) {
  throw new Error('Could not parse brand_id from URL: ' + url);
}

if (!name) throw new Error('Brand Name is required.');
if (!sinceDateRaw) throw new Error('Monitor since date is required.');

// Normalize date to YYYY-MM-DD
const sinceDate = new Date(sinceDateRaw).toISOString().slice(0, 10);
const today = new Date().toISOString().slice(0, 10);
const isPastDate = sinceDate < today;
const backfillRequested = backfillChoice.toLowerCase().startsWith('yes');
const shouldBackfill = backfillRequested && isPastDate;

// Slug for the brands.slug column
const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

return [{
  json: {
    gethookd_brand_id: gethookdBrandId,
    name: name,
    slug: slug,
    monitor_since_date: sinceDate,
    account_type: ['main','tof','whitelist'].includes(accountType) ? accountType : 'main',
    should_backfill: shouldBackfill,
    facebook_page_url: null,
    // Required-NOT-NULL columns get defaults so the INSERT succeeds:
    status: 'active',
    total_ads_count: 0,
    voice_config: {},
    personas: [],
    operational_risk_status: {},
    compliance_status: 'unknown'
  }
}];

// Insert returns an array with the created brand row. Carry brand.id forward.
const extracted = $('Extract & Validate').first().json;
const inserted = $input.first().json;
const brandRow = Array.isArray(inserted) ? inserted[0] : inserted;
if (!brandRow || !brandRow.id) {
  throw new Error('Supabase insert did not return a brand row. Response: ' + JSON.stringify(inserted).slice(0, 300));
}
return [{ json: { brand_id: brandRow.id, should_backfill: extracted.should_backfill } }];
